import{_ as o,r as n,o as p,c as l,e as s,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Importing & Exporting - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Configuring the Behavior","slug":"configuring-the-behavior","link":"#configuring-the-behavior","children":[{"level":3,"title":"Import Page","slug":"import-page","link":"#import-page","children":[]},{"level":3,"title":"Export Page","slug":"export-page","link":"#export-page","children":[]},{"level":3,"title":"Format Options","slug":"format-options","link":"#format-options","children":[]}]},{"level":2,"title":"Import and Export Views","slug":"import-and-export-views","link":"#import-and-export-views","children":[{"level":3,"title":"Import View","slug":"import-view","link":"#import-view","children":[]},{"level":3,"title":"Export View","slug":"export-view","link":"#export-view","children":[]}]},{"level":2,"title":"Defining an Import Model","slug":"defining-an-import-model","link":"#defining-an-import-model","children":[]},{"level":2,"title":"Defining an Export Model","slug":"defining-an-export-model","link":"#defining-an-export-model","children":[]},{"level":2,"title":"Custom Options","slug":"custom-options","link":"#custom-options","children":[]},{"level":2,"title":"Integration with List Behavior","slug":"integration-with-list-behavior","link":"#integration-with-list-behavior","children":[]}],"relativePath":"2.x/backend/import-export.md","filePath":"2.x/backend/import-export.md"}'),i={name:"2.x/backend/import-export.md"};function u(d,a,k,g,m,h){const t=n("pre-heading"),e=n("post-heading");return p(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"Importing & Exporting",-1)),s(e),a[1]||(a[1]=r(`<p><strong>Import Export Behavior</strong> is a controller modifier that provides features for importing and exporting data. The behavior provides two pages called Import and Export. The Import page allows a user to upload a CSV file and match the columns to the database. The Export page is the opposite and allows a user to download columns from the database as a CSV file. The behavior provides the controller actions <code>import()</code> and <code>export()</code>.</p><p>The behavior configuration is defined in two parts, each part depends on a special model class along with a list and form field definition file. To use the importing and exporting behavior you should add it to the <code>$implement</code> property of the controller class. Also, the <code>$importExportConfig</code> class property should be defined and its value should refer to the YAML file used for configuring the behavior options.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Shop<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Products</span> <span class="token keyword">extends</span> <span class="token class-name">Controller</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$implement</span> <span class="token operator">=</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Behaviors<span class="token punctuation">\\</span>ImportExportController</span><span class="token operator">::</span><span class="token keyword">class</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$importExportConfig</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;config_import_export.yaml&#39;</span><span class="token punctuation">;</span>

    <span class="token comment">// [...]</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="configuring-the-behavior"><a href="#configuring-the-behavior" class="header-anchor">#</a> Configuring the Behavior</h2><p>The configuration file referred in the <code>$importExportConfig</code> property is defined in YAML format. The file should be placed into the controller&#39;s <a href="./controllers-ajax.html">views directory</a>. Below is an example of a configuration file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Import/Export Behavior Config</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">import</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Import subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberImport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriber/columns.yaml

<span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Export subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberExport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriber/columns.yaml
</code></pre></div><p>The configuration options listed below are optional. Define them if you want the behavior to support the <a href="#oc-import-page">Import</a> or <a href="#oc-export-page">Export</a>, or both.</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>defaultRedirect</strong></td><td>used as a fallback redirection page when no specific redirect page is defined.</td></tr><tr><td><strong>import</strong></td><td>a configuration array or reference to a config file for the Import page.</td></tr><tr><td><strong>export</strong></td><td>a configuration array or reference to a config file for the Export page.</td></tr><tr><td><strong>defaultFormatOptions</strong></td><td>a configuration array or reference to a config file for the default CSV format options.</td></tr></tbody></table></div><p><a id="oc-import-page"></a></p><h3 id="import-page"><a href="#import-page" class="header-anchor">#</a> Import Page</h3><p>To support the Import page add the following configuration to the YAML file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">import</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Import subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberImport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberimport/columns.yaml
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/campaign/subscribers
</code></pre></div><p>The following configuration options are supported for the Import page:</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>a page title, can refer to a <a href="./../plugin/localization.html">localization string</a>.</td></tr><tr><td><strong>list</strong></td><td>defines the list columns available for importing.</td></tr><tr><td><strong>form</strong></td><td>provides additional fields used as import options, optional.</td></tr><tr><td><strong>redirect</strong></td><td>redirection page when the import is complete, optional</td></tr><tr><td><strong>permissions</strong></td><td>user permissions needed to perform the operation, optional</td></tr></tbody></table></div><p><a id="oc-export-page"></a></p><h3 id="export-page"><a href="#export-page" class="header-anchor">#</a> Export Page</h3><p>To support the Export page add the following configuration to the YAML file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span> Export subscribers
    <span class="token key atrule">modelClass</span><span class="token punctuation">:</span> Acme\\Campaign\\Models\\SubscriberExport
    <span class="token key atrule">list</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberexport/columns.yaml
    <span class="token key atrule">redirect</span><span class="token punctuation">:</span> acme/campaign/subscribers
</code></pre></div><p>The following configuration options are supported for the Export page:</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>title</strong></td><td>a page title, can refer to a <a href="./../plugin/localization.html">localization string</a>.</td></tr><tr><td><strong>fileName</strong></td><td>the file name to use for the exported file, default <strong>export.csv</strong>.</td></tr><tr><td><strong>list</strong></td><td>defines the list columns available for exporting.</td></tr><tr><td><strong>form</strong></td><td>provides additional fields used as export options, optional.</td></tr><tr><td><strong>redirect</strong></td><td>redirection page when the export is complete, optional.</td></tr><tr><td><strong>useList</strong></td><td>set to true or the value of a list definition to enable <a href="#oc-list-behavior-integration">integration with Lists</a>, default: false.</td></tr></tbody></table></div><h3 id="format-options"><a href="#format-options" class="header-anchor">#</a> Format Options</h3><p>To override the default CSV format options add the following configuration to the YAML file:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">defaultFormatOptions</span><span class="token punctuation">:</span>
    <span class="token key atrule">delimiter</span><span class="token punctuation">:</span> <span class="token string">&#39;;&#39;</span>
    <span class="token key atrule">enclosure</span><span class="token punctuation">:</span> <span class="token string">&#39;&quot;&#39;</span>
    <span class="token key atrule">escape</span><span class="token punctuation">:</span> &#39;\\&#39;
    <span class="token key atrule">encoding</span><span class="token punctuation">:</span> <span class="token string">&#39;utf-8&#39;</span>
</code></pre></div><p>The following configuration options (all optional) are supported for the format options:</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>delimiter</strong></td><td>Delimiter character.</td></tr><tr><td><strong>enclosure</strong></td><td>Enclosure character.</td></tr><tr><td><strong>escape</strong></td><td>Escape character.</td></tr><tr><td><strong>encoding</strong></td><td>File encoding (only used for the import).</td></tr></tbody></table></div><h2 id="import-and-export-views"><a href="#import-and-export-views" class="header-anchor">#</a> Import and Export Views</h2><p>For each page feature <a href="#oc-import-page">Import</a> and <a href="#oc-export-page">Export</a> you should provide a <a href="./controllers-ajax.html">view file</a> with the corresponding name - <strong>import.htm</strong> and <strong>export.htm</strong>.</p><p>The import/export behavior adds two methods to the controller class: <code>importRender</code> and <code>exportRender</code>. These methods render the importing and exporting sections as per the YAML configuration file described above.</p><h3 id="import-view"><a href="#import-view" class="header-anchor">#</a> Import View</h3><p>The <strong>import.htm</strong> view represents the Import page that allows users to import data. A typical Import page contains breadcrumbs, the import section itself, and the submission buttons. The <strong>data-request</strong> attribute should refer to the <code>onImport</code> AJAX handler provided by the behavior. Below is a contents of the typical import.htm view file.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;layout&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>layout-row<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">importRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
            <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>popup<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-handler</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onImportLoadForm<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-keyboard</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            Import records
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="export-view"><a href="#export-view" class="header-anchor">#</a> Export View</h3><p>The <strong>export.htm</strong> view represents the Export page that allows users to export a file from the database. A typical Export page contains breadcrumbs, the export section itself, and the submission buttons. The <strong>data-request</strong> attribute should refer to the <code>onExport</code> AJAX handler provided by the behavior. Below is a contents of the typical export.htm form.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;layout&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>layout-row<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">exportRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
            <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>popup<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-handler</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onExportLoadForm<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">data-keyboard</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span>
            <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-primary<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            Export records
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>

<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="defining-an-import-model"><a href="#defining-an-import-model" class="header-anchor">#</a> Defining an Import Model</h2><p>For importing data you should create a dedicated model for this process which extends the <code>Backend\\Models\\ImportModel</code> class. Here is an example class definition:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">SubscriberImport</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>ImportModel</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var array The rules to be applied to the data.
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$rules</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">importData</span><span class="token punctuation">(</span><span class="token variable">$results</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$results</span> <span class="token keyword">as</span> <span class="token variable">$row</span> <span class="token operator">=&gt;</span> <span class="token variable">$data</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>

            <span class="token keyword">try</span> <span class="token punctuation">{</span>
                <span class="token variable">$subscriber</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Subscriber</span><span class="token punctuation">;</span>
                <span class="token variable">$subscriber</span><span class="token operator">-&gt;</span><span class="token function">fill</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
                <span class="token variable">$subscriber</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

                <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">logCreated</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>
            <span class="token keyword">catch</span> <span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Exception</span> <span class="token variable">$ex</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
                <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">logError</span><span class="token punctuation">(</span><span class="token variable">$row</span><span class="token punctuation">,</span> <span class="token variable">$ex</span><span class="token operator">-&gt;</span><span class="token function">getMessage</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token punctuation">}</span>

        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The class must define a method called <code>importData</code> used for processing the imported data. The first parameter <code>$results</code> will contain an array containing the data to import. The second parameter <code>$sessionKey</code> will contain the session key used for the request.</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>logUpdated()</code></td><td>Called when a record is updated.</td></tr><tr><td><code>logCreated()</code></td><td>Called when a record is created.</td></tr><tr><td><code>logError(rowIndex, message)</code></td><td>Called when there is a problem with importing the record.</td></tr><tr><td><code>logWarning(rowIndex, message)</code></td><td>Used to provide a soft warning, like modifying a value.</td></tr><tr><td><code>logSkipped(rowIndex, message)</code></td><td>Used when the entire row of data was not imported (skipped).</td></tr></tbody></table></div><h2 id="defining-an-export-model"><a href="#defining-an-export-model" class="header-anchor">#</a> Defining an Export Model</h2><p>For exporting data you should create a dedicated model which extends the <code>Backend\\Models\\ExportModel</code> class. Here is an example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">SubscriberExport</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>ExportModel</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">exportData</span><span class="token punctuation">(</span><span class="token variable">$columns</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$subscribers</span> <span class="token operator">=</span> <span class="token class-name static-context">Subscriber</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token variable">$subscribers</span><span class="token operator">-&gt;</span><span class="token function">each</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$subscriber</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$columns</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token variable">$subscriber</span><span class="token operator">-&gt;</span><span class="token function">addVisible</span><span class="token punctuation">(</span><span class="token variable">$columns</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

        <span class="token keyword">return</span> <span class="token variable">$subscribers</span><span class="token operator">-&gt;</span><span class="token function">toArray</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The class must define a method called <code>exportData</code> used for returning the export data. The first parameter <code>$columns</code> is an array of column names to export. The second parameter <code>$sessionKey</code> will contain the session key used for the request.</p><h2 id="custom-options"><a href="#custom-options" class="header-anchor">#</a> Custom Options</h2><p>Both import and export forms support custom options that can be introduced using form fields, defined in the <strong>form</strong> option in the import or export configuration respectively. These values are then passed to the Import / Export model and are available during processing.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">import</span><span class="token punctuation">:</span>
    <span class="token comment"># ...</span>
    <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberimport/fields.yaml

<span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token comment"># ...</span>
    <span class="token key atrule">form</span><span class="token punctuation">:</span> $/acme/campaign/models/subscriberexport/fields.yaml
</code></pre></div><p>The form fields specified will appear on the import/export page. Here is an example <code>fields.yaml</code> file contents:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token comment"># ===================================</span>
<span class="token comment">#  Form Field Definitions</span>
<span class="token comment"># ===================================</span>

<span class="token key atrule">fields</span><span class="token punctuation">:</span>

    <span class="token key atrule">auto_create_lists</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Automatically create lists
        <span class="token key atrule">type</span><span class="token punctuation">:</span> checkbox
        <span class="token key atrule">default</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>The value of the form field above called <strong>auto_create_lists</strong> can be accessed using <code>$this-&gt;auto_create_lists</code> inside the <code>importData</code> method of the import model. If this were the export model, the value would be available inside the <code>exportData</code> method instead.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">SubscriberImport</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>ImportModel</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">importData</span><span class="token punctuation">(</span><span class="token variable">$results</span><span class="token punctuation">,</span> <span class="token variable">$sessionKey</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">auto_create_lists</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token comment">// Do something</span>
        <span class="token punctuation">}</span>

        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-list-behavior-integration"></a></p><h2 id="integration-with-list-behavior"><a href="#integration-with-list-behavior" class="header-anchor">#</a> Integration with List Behavior</h2><p>There is an alternative approach to exporting data that uses the <a href="./lists.html">list behavior</a> to provide the export data. In order to use this feature you should have the <code>Backend\\Behaviors\\ListController</code> definition to the <code>$implement</code> field of the controller class. You do not need to use an export view and all the settings will be pulled from the list. Here is the only configuration needed:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>Then simply add button to the <a href="./lists.html">list toolbar</a>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Backend</span><span class="token operator">::</span><span class="token function">url</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme/campaign/subscribers/export&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default oc-icon-download<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Export Records
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>If you are using <a href="./lists.html#oc-multiple-list-definitions">multiple list definitions</a>, then you can supply the list definition:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span> orders
    <span class="token key atrule">fileName</span><span class="token punctuation">:</span> orders.csv
</code></pre></div><p>The <code>useList</code> option also supports extended configuration options.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">export</span><span class="token punctuation">:</span>
    <span class="token key atrule">useList</span><span class="token punctuation">:</span>
        <span class="token key atrule">definition</span><span class="token punctuation">:</span> orders
        <span class="token key atrule">raw</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>The following configuration options are supported:</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>definition</strong></td><td>the list definition to source records from, optional.</td></tr><tr><td><strong>raw</strong></td><td>output the raw attribute values from the record, default: false.</td></tr></tbody></table></div>`,62))])}const v=o(i,[["render",u]]);export{b as __pageData,v as default};
